<script setup lang="ts">
import {ref,computed} from 'vue';import {api} from '@/services/api';import type {LicenseStatus} from '@/services/api';import PufferMark from './PufferMark.vue';
const props=defineProps<{status:LicenseStatus|null;canReturn:boolean;issue?:string}>();const emit=defineEmits<{changed:[status:LicenseStatus];close:[];logout:[]}>();const key=ref(''),busy=ref(false),error=ref(''),message=ref('');const themeDesktop=import.meta.env.VITE_HETUN_THEME_DESKTOP==='1';const allProducts=[{id:'film-center' as const,name:'影视中心',description:'内容连接、运营管理与客户端服务'},{id:'theme' as const,name:'主题中心',description:'骨架安装、主题编辑与发布'}];const products=themeDesktop?allProducts.filter(p=>p.id==='theme'):allProducts;const ready=computed(()=>props.status?.trustConfigured);
async function settings(){await (window as any).hetunTheme?.settings();}
async function run(action:'activate'|'refresh'|'clear'){if(busy.value)return;if(action==='clear'){const answer=await new Promise<boolean>(resolve=>uni.showModal({title:'移除本机授权',content:'移除后影视中心与主题编辑将锁定，云端授权记录仍保留。',success:r=>resolve(r.confirm)}));if(!answer)return;}busy.value=true;error.value='';message.value='';try{const status=await(action==='activate'?api.activateLicense(key.value):action==='clear'?api.clearLicense():api.license());key.value='';emit('changed',status);message.value=action==='activate'?'授权已验证并保存。':action==='clear'?'本机授权已移除。':'授权状态已刷新。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><view class="license-page"><view class="license-shell"><view class="license-header"><view class="license-brand"><PufferMark :size="48" framed/><view><text class="eyebrow">HETUN CINEMA CENTER</text><text class="license-title">授权管理</text></view></view><view class="license-actions"><button v-if="canReturn" @click="emit('close')">返回工作台</button><button @click="emit('logout')">退出登录</button></view></view><text class="license-intro">{{themeDesktop?'主题制作软件独立授权，按绑定域名和有效期校验。':'影视中心与主题独立授权，按绑定域名和有效期校验。'}}</text><button v-if="themeDesktop" @click="settings">服务设置</button><view class="license-products"><view v-for="product in products" :key="product.id" class="license-card"><view class="license-card-top"><text class="product-name">{{product.name}}</text><text class="license-badge" :class="{valid:status?.products[product.id]?.valid}">{{status?.products[product.id]?.valid?'已授权':'待授权'}}</text></view><text class="product-description">{{product.description}}</text><text class="license-detail">{{status?.products[product.id]?.valid?'云端签名验证通过':status?.products[product.id]?.message||'正在读取授权状态'}}</text><text v-if="product.id==='theme'&&status?.products.theme.valid" class="license-detail">可用主题：{{status.products.theme.themes?.includes('*')?'全部主题':status.products.theme.themes?.join('、')||'未配置主题范围'}}</text></view></view><view class="license-connection"><view><text>绑定域名</text><text>{{status?.domain||'读取中'}}</text></view><view><text>授权服务</text><text>{{status?.url||'尚未配置'}}</text></view></view><view v-if="!ready" class="license-notice">部署环境尚未配置授权服务或可信公钥，请先完成服务配置。</view><view class="license-input"><text>授权 Key</text><input v-model="key" password placeholder="输入云端后台生成的授权 Key" :disabled="busy" @confirm="run('activate')"/><text class="license-help">Key 由服务器保存，浏览器不保存授权密钥。</text></view><view v-if="error||issue" class="license-error">{{error||issue}}</view><view v-if="message" class="license-success">{{message}}</view><view class="license-buttons"><button class="license-primary" :disabled="busy||!ready||!key" @click="run('activate')">{{busy?'正在校验…':'激活授权'}}</button><button :disabled="busy" @click="run('refresh')">刷新状态</button><button v-if="status?.keyConfigured" :disabled="busy" @click="run('clear')">移除本机授权</button></view></view></view></template>
<style scoped>
.license-page{min-height:100vh;display:flex;align-items:center;justify-content:center;padding:40px;background:#10131a;color:#eef0f4;box-sizing:border-box}.license-shell{width:min(860px,100%);border:1px solid #2b303b;border-radius:24px;background:#171b24;padding:36px;box-sizing:border-box}.license-header,.license-brand,.license-actions,.license-card-top,.license-buttons{display:flex;align-items:center;gap:14px}.license-header,.license-card-top{justify-content:space-between}.license-brand>view{display:flex;flex-direction:column;gap:6px}.eyebrow{font-size:10px;letter-spacing:2px;color:#a7aebb}.license-title{font-size:26px;font-weight:700}.license-intro{display:block;color:#aab1c0;font-size:14px;margin:24px 0}.license-products{display:grid;grid-template-columns:1fr 1fr;gap:16px}.license-card{border:1px solid #303643;border-radius:16px;padding:22px;min-width:0}.product-name{font-size:18px;font-weight:600}.license-badge{background:#39302b;color:#e7b883;padding:5px 10px;border-radius:8px;font-size:12px}.license-badge.valid{background:#1f3b32;color:#96ddbd}.product-description,.license-detail{display:block;line-height:1.7;color:#a5adbc;font-size:13px;margin-top:14px;overflow-wrap:anywhere}.license-detail{font-size:12px;margin-top:10px}.license-connection{margin:24px 0;display:grid;gap:12px}.license-connection>view{display:flex;justify-content:space-between;gap:20px;font-size:13px;overflow-wrap:anywhere}.license-connection>view>text:first-child{color:#929aaa;white-space:nowrap}.license-input>text{display:block;margin:10px 0;font-size:14px}.license-input input{height:46px;border:1px solid #3c4352;border-radius:10px;padding:0 14px;font-size:14px;background:#11151e;color:white}.license-input .license-help{font-size:12px;color:#939dad}.license-notice,.license-error,.license-success{padding:12px 16px;border-radius:10px;font-size:13px;line-height:1.7;margin:16px 0;background:#362d22;color:#efc18e}.license-error{background:#38252b;color:#f6a4b4}.license-success{background:#20352c;color:#99d9b5}.license-buttons{margin-top:24px;flex-wrap:wrap}.license-page button{background:#252b37;color:#e5e9f0;border:1px solid #3a4353;border-radius:10px;font-size:13px;line-height:40px;margin:0;padding:0 16px}.license-page button::after{border:0}.license-page button.license-primary{background:#d4ad70;border-color:#d4ad70;color:#17191e;font-weight:600}.license-page button[disabled]{opacity:.45}.center-light .license-page{background:#eef1f6;color:#202532}.center-light .license-shell{background:white;border-color:#d8dde6}.center-light .license-card{border-color:#d8dde6}.center-light .license-input input{background:#f4f6fa;color:#202532;border-color:#d0d6e1}.center-light .license-page button{background:#edf0f5;color:#202532;border-color:#d0d6e1}.center-light .license-page button.license-primary{background:#bd9254;color:white}@media(max-width:700px){.license-page{padding:16px;align-items:flex-start}.license-shell{padding:22px}.license-header{align-items:flex-start;flex-wrap:wrap}.license-products{grid-template-columns:1fr}.license-actions{margin-left:0}.license-title{font-size:23px}.license-connection>view{flex-direction:column;gap:4px}}
</style>
